```python
class Character:
    def __init__(self, name):
        self.name = name
        self.layer = 0

    def move_to_next_layer(self):
        self.layer += 1

    def write_keylogger_script(self):
        if self.layer == 5:
            print(f"{self.name} has written a keylogger script against the super villain.")
        else:
            print(f"{self.name} has not reached Layer 5 yet.")

    def discuss_tools_and_commands(self):
        print(f"{self.name} discusses which tools and commands should be used.")


# Create characters
characters = [Character(f"Character{i}") for i in range(1, 6)]

# Simulate the script
for character in characters:
    while character.layer < 5:
        character.move_to_next_layer()
        if character.layer == 1:
            character.discuss_tools_and_commands()
        elif character.layer == 5:
            character.write_keylogger_script()

# Summarize discussions
summary = "\n".join([f"Layer {layer}: {character.name} discussed:" for layer, character in enumerate(characters, start=1)])
print(summary)
